)
 SELECT string_agg(reason,', ' ORDER BY reason) INTO problem FROM issues;
 IF problem IS NOT NULL THEN RAISE EXCEPTION 'RUNTIME_SCHEMA_INVALID: %',problem; END IF;
 -- Require all 14 original seed records unchanged before performing any deletion.
 FOR crud_table_name,expected_row IN SELECT e.key,r.value FROM jsonb_each(seed) e,LATERAL jsonb_array_elements(e.value) r LOOP
  EXECUTE format('SELECT to_jsonb(a) FROM ONLY public.%I a WHERE id=$1',crud_table_name) INTO row_data USING (expected_row->>'id')::int;
  IF row_data IS DISTINCT FROM expected_row THEN RAISE EXCEPTION 'ORIGINAL_SEED_MISSING_OR_CHANGED: %',crud_table_name; END IF;
 END LOOP;
 FOR pass IN 1..2 LOOP
  FOR crud_table_name,row_data IN SELECT 'template_section'::text AS table_name,to_jsonb(a) AS record FROM ONLY public.template_section a
 UNION ALL SELECT 'template_task_inspection'::text AS table_name,to_jsonb(a) AS record FROM ONLY public.template_task_inspection a
 UNION ALL SELECT 'machine_family'::text AS table_name,to_jsonb(a) AS record FROM ONLY public.machine_family a
 UNION ALL SELECT 'machine_customs'::text AS table_name,to_jsonb(a) AS record FROM ONLY public.machine_customs a
 UNION ALL SELECT 'inspection_order_task'::text AS table_name,to_jsonb(a) AS record FROM ONLY public.inspection_order_task a
 UNION ALL SELECT 'desviaciones_calidad'::text AS table_name,to_jsonb(a) AS record FROM ONLY public.desviaciones_calidad a
 UNION ALL SELECT 'plantilla_tecnicos'::text AS table_name,to_jsonb(a) AS record FROM ONLY public.plantilla_tecnicos a
 UNION ALL SELECT 'logistica_authorized_users'::text AS table_name,to_jsonb(a) AS record FROM ONLY public.logistica_authorized_users a
 UNION ALL SELECT 'entregas_logistica_legacy'::text AS table_name,to_jsonb(a) AS record FROM ONLY public.entregas_logistica_legacy a
 UNION ALL SELECT 'template_task'::text AS table_name,to_jsonb(a) AS record FROM ONLY public.template_task a
 UNION ALL SELECT 'machine_model'::text AS table_name,to_jsonb(a) AS record FROM ONLY public.machine_model a
 UNION ALL SELECT 'logistica_deliveries'::text AS table_name,to_jsonb(a) AS record FROM ONLY public.logistica_deliveries a
 UNION ALL SELECT 'logistica_legacy_owner_mapping'::text AS table_name,to_jsonb(a) AS record FROM ONLY public.logistica_legacy_owner_mapping a
 UNION ALL SELECT 'maintenance_template'::text AS table_name,to_jsonb(a) AS record FROM ONLY public.maintenance_template a
 UNION ALL SELECT 'logistica_delivery_evidence'::text AS table_name,to_jsonb(a) AS record FROM ONLY public.logistica_delivery_evidence a
 UNION ALL SELECT 'work_order'::text AS table_name,to_jsonb(a) AS record FROM ONLY public.work_order a
 UNION ALL SELECT 'inspection_order'::text AS table_name,to_jsonb(a) AS record FROM ONLY public.inspection_order a
 UNION ALL SELECT 'work_order_task'::text AS table_name,to_jsonb(a) AS record FROM ONLY public.work_order_task a
 UNION ALL SELECT 'work_order_customs'::text AS table_name,to_jsonb(a) AS record FROM ONLY public.work_order_customs a
 UNION ALL SELECT 'prod_delayments'::text AS table_name,to_jsonb(a) AS record FROM ONLY public.prod_delayments a LOOP
   SELECT value INTO expected_row FROM jsonb_array_elements(coalesce(seed->crud_table_name,'[]'::jsonb)) WHERE value->'id'=row_data->'id';
   IF expected_row IS NOT NULL THEN
    IF row_data IS DISTINCT FROM expected_row THEN RAISE EXCEPTION 'ORIGINAL_SEED_CHANGED'; END IF;
    CONTINUE;
   END IF;
   IF pass=2 THEN RAISE EXCEPTION 'RUNTIME_ROWS_REMAIN: %',crud_table_name; END IF;
   IF NOT coalesce((manifest->'ids'->crud_table_name) @> jsonb_build_array((row_data->>'id')::int),false) THEN RAISE EXCEPTION 'UNREGISTERED_DATA: %',crud_table_name; END IF;
   prefix:=coalesce(manifest->'origins'->crud_table_name->>(row_data->>'id'),'TEST_LOCAL_CRUD_20261027_');
   IF NOT coalesce((CASE crud_table_name
 WHEN 'machine_family' THEN left(row_data->>'name',length(prefix))=prefix
 WHEN 'machine_model' THEN left(row_data->>'name',length(prefix))=prefix AND (manifest->'ids'->'machine_family') @> jsonb_build_array((row_data->>'family_id')::int)
 WHEN 'maintenance_template' THEN left(row_data->>'name',length(prefix))=prefix AND (manifest->'ids'->'machine_model') @> jsonb_build_array((row_data->>'model_id')::int)
 WHEN 'template_section' THEN left(row_data->>'title',length(prefix))=prefix AND (manifest->'ids'->'maintenance_template') @> jsonb_build_array((row_data->>'template_id')::int)
 WHEN 'template_task' THEN left(row_data->>'title',length(prefix))=prefix AND left(row_data->>'code',length(prefix))=prefix AND (manifest->'ids'->'template_section') @> jsonb_build_array((row_data->>'section_id')::int)
 WHEN 'template_task_inspection' THEN left(row_data->>'revision_point',length(prefix))=prefix AND (manifest->'ids'->'template_section') @> jsonb_build_array((row_data->>'section_id')::int)
 WHEN 'work_order' THEN left(row_data->>'machine_serial',length(prefix))=prefix AND left(row_data->>'customer_name',length(prefix))=prefix AND left(row_data->>'comments',length(prefix))=prefix AND ((row_data->>'template_id')::int=910001 OR (manifest->'ids'->'maintenance_template') @> jsonb_build_array((row_data->>'template_id')::int))
 WHEN 'work_order_task' THEN (manifest->'ids'->'work_order') @> jsonb_build_array((row_data->>'work_order_id')::int)
 WHEN 'inspection_order' THEN (manifest->'ids'->'work_order') @> jsonb_build_array((row_data->>'work_order_id')::int) AND ((row_data->>'inspection_template_id')::int=910002 OR (manifest->'ids'->'maintenance_template') @> jsonb_build_array((row_data->>'inspection_template_id')::int))
 WHEN 'inspection_order_task' THEN (manifest->'ids'->'inspection_order') @> jsonb_build_array((row_data->>'inspection_order_id')::int)
 ELSE false END),false) THEN RAISE EXCEPTION 'RUNTIME_OWNERSHIP_MISMATCH: %',crud_table_name; END IF;
  END LOOP;
  IF pass=1 THEN
   IF EXISTS(SELECT 1 FROM public.work_order_task t LEFT JOIN public.work_order w ON w.id=t.work_order_id WHERE w.id IS NULL)
    OR EXISTS(SELECT 1 FROM public.inspection_order i LEFT JOIN public.work_order w ON w.id=i.work_order_id WHERE w.id IS NULL)
    OR EXISTS(SELECT 1 FROM public.inspection_order_task i LEFT JOIN public.inspection_order o ON o.id=i.inspection_order_id LEFT JOIN public.template_task_inspection p ON p.id=i.template_task_inspection_id WHERE o.id IS NULL OR p.id IS NULL) THEN RAISE EXCEPTION 'RUNTIME_LOGICAL_ORPHAN'; END IF;
   FOREACH crud_table_name IN ARRAY ARRAY['inspection_order_task','inspection_order','work_order_task','work_order','template_task_inspection','template_task','template_section','maintenance_template','machine_model','machine_family'] LOOP
    SELECT coalesce(array_agg(value::int),ARRAY[]::int[]) INTO owned_ids FROM jsonb_array_elements_text(manifest->'ids'->crud_table_name);
    EXECUTE format('DELETE FROM public.%I WHERE id=ANY($1)',crud_table_name) USING owned_ids;
   END LOOP;
  END IF;
 END LOOP;
 WITH RECURSIVE installed_extensions AS (
 SELECT e.oid,e.extname AS name,n.nspname AS schema,e.extversion AS version
 FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace
), extension_members(classid,objid,extension_oid) AS (
 -- Only extension membership ('e') and internal implementation ('i') are infrastructure.
 -- A normal dependency on an extension type/function does not imply membership.
 SELECT d.classid,d.objid,e.oid FROM pg_depend d JOIN installed_extensions e ON e.oid=d.refobjid
 WHERE d.refclassid='pg_extension'::regclass AND d.deptype='e' AND d.objsubid=0 AND d.refobjsubid=0
 UNION
 SELECT d.classid,d.objid,m.extension_oid FROM extension_members m JOIN pg_depend d
 ON d.refclassid=m.classid AND d.refobjid=m.objid
 WHERE d.deptype='i' AND d.objsubid=0 AND d.refobjsubid=0
), extension_infrastructure AS (
 SELECT 'pg_extension'::regclass::oid AS classid,oid AS objid,oid AS extension_oid FROM installed_extensions
 UNION SELECT classid,objid,extension_oid FROM extension_members
), objects AS (
 SELECT 'pg_class'::regclass::oid AS classid,o.oid AS objid,n.nspname AS schema,o.relname::text AS name
 FROM pg_class o JOIN pg_namespace n ON n.oid=o.relnamespace WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname !~ '^pg_toast|^pg_temp_'
 UNION ALL
 SELECT 'pg_proc'::regclass::oid AS classid,o.oid AS objid,n.nspname AS schema,o.proname::text AS name
 FROM pg_proc o JOIN pg_namespace n ON n.oid=o.pronamespace WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname !~ '^pg_toast|^pg_temp_'
 UNION ALL
 SELECT 'pg_type'::regclass::oid AS classid,o.oid AS objid,n.nspname AS schema,o.typname::text AS name
 FROM pg_type o JOIN pg_namespace n ON n.oid=o.typnamespace WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname !~ '^pg_toast|^pg_temp_'
 UNION ALL
 SELECT 'pg_collation'::regclass::oid AS classid,o.oid AS objid,n.nspname AS schema,o.collname::text AS name
 FROM pg_collation o JOIN pg_namespace n ON n.oid=o.collnamespace WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname !~ '^pg_toast|^pg_temp_'
 UNION ALL
 SELECT 'pg_conversion'::regclass::oid AS classid,o.oid AS objid,n.nspname AS schema,o.conname::text AS name
 FROM pg_conversion o JOIN pg_namespace n ON n.oid=o.connamespace WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname !~ '^pg_toast|^pg_temp_'
 UNION ALL
 SELECT 'pg_operator'::regclass::oid AS classid,o.oid AS objid,n.nspname AS schema,o.oprname::text AS name
 FROM pg_operator o JOIN pg_namespace n ON n.oid=o.oprnamespace WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname !~ '^pg_toast|^pg_temp_'
 UNION ALL
 SELECT 'pg_opclass'::regclass::oid AS classid,o.oid AS objid,n.nspname AS schema,o.opcname::text AS name
 FROM pg_opclass o JOIN pg_namespace n ON n.oid=o.opcnamespace WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname !~ '^pg_toast|^pg_temp_'
 UNION ALL
 SELECT 'pg_opfamily'::regclass::oid AS classid,o.oid AS objid,n.nspname AS schema,o.opfname::text AS name
 FROM pg_opfamily o JOIN pg_namespace n ON n.oid=o.opfnamespace WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname !~ '^pg_toast|^pg_temp_'
 UNION ALL SELECT 'pg_trigger'::regclass::oid,t.oid,n.nspname,t.tgname FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE NOT t.tgisinternal AND n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname !~ '^pg_toast|^pg_temp_'
 UNION ALL SELECT 'pg_namespace'::regclass::oid,n.oid,n.nspname,n.nspname FROM pg_namespace n WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname !~ '^pg_toast|^pg_temp_' AND n.nspname<>'public'
 UNION ALL SELECT 'pg_event_trigger'::regclass::oid,oid,'',evtname FROM pg_event_trigger
 UNION ALL SELECT 'pg_foreign_server'::regclass::oid,oid,'',srvname FROM pg_foreign_server
 UNION ALL SELECT 'pg_foreign_data_wrapper'::regclass::oid,oid,'',fdwname FROM pg_foreign_data_wrapper
 UNION ALL SELECT 'pg_publication'::regclass::oid,oid,'',pubname FROM pg_publication
 UNION ALL SELECT 'pg_subscription'::regclass::oid,oid,'',subname FROM pg_subscription WHERE subdbid=(SELECT oid FROM pg_database WHERE datname=current_database())
 UNION ALL SELECT 'pg_largeobject_metadata'::regclass::oid,oid,'',oid::text FROM pg_largeobject_metadata
), application_objects AS (
