 expected_tables(name) AS (VALUES ('template_section'),('template_task_inspection'),('machine_family'),('machine_customs'),('inspection_order_task'),('desviaciones_calidad'),('plantilla_tecnicos'),('logistica_schema_migrations'),('logistica_authorized_users'),('entregas_logistica_legacy'),('template_task'),('machine_model'),('logistica_deliveries'),('logistica_legacy_owner_mapping'),('maintenance_template'),('logistica_delivery_evidence'),('work_order'),('inspection_order'),('work_order_task'),('work_order_customs'),('prod_delayments')),
 counts AS (
 SELECT e.name,c.oid,c.relkind,c.relpersistence,c.relrowsecurity,c.relforcerowsecurity,x.rows::bigint AS rows
 FROM expected_tables e LEFT JOIN pg_class c ON c.oid=to_regclass('public.'||e.name)
 CROSS JOIN LATERAL XMLTABLE('/table/row' PASSING query_to_xml(
 CASE WHEN c.relkind='r' AND NOT c.relrowsecurity AND NOT c.relforcerowsecurity
 THEN format('SELECT count(*) AS rows FROM ONLY public.%I',e.name) ELSE 'SELECT NULL::bigint AS rows' END,
 false,false,'') COLUMNS rows text PATH 'rows') x
), base_tables AS (SELECT t FROM expected,LATERAL jsonb_array_elements(value->'base') t),
 columns AS (SELECT t->>'name' AS table_name,c,ordinality AS position FROM base_tables,LATERAL jsonb_array_elements(t->'columns') WITH ORDINALITY a(c,ordinality)),
 constraints AS (SELECT t->>'name' AS table_name,k FROM base_tables,LATERAL jsonb_array_elements(t->'constraints') k),
 indexes AS (SELECT i FROM expected,LATERAL jsonb_array_elements(value->'indexes') i),
 functions AS (SELECT f FROM expected,LATERAL jsonb_array_elements(value->'functions') f),
 sequences AS (SELECT s FROM expected,LATERAL jsonb_array_elements(value->'sequences') s),
 sequence_state AS (SELECT s,x.* FROM sequences CROSS JOIN LATERAL XMLTABLE('/table/row' PASSING query_to_xml(
 CASE WHEN EXISTS(SELECT FROM pg_class WHERE oid=to_regclass('public.'||(s->>'name')) AND relkind='S')
 THEN format('SELECT last_value,is_called FROM public.%I',s->>'name') ELSE 'SELECT NULL::bigint AS last_value,NULL::boolean AS is_called' END,
 false,false,'') COLUMNS last_value text PATH 'last_value',is_called text PATH 'is_called') x),
 ledger_expected AS (SELECT f,ordinality AS position FROM expected,LATERAL jsonb_array_elements(value->'ledger') WITH ORDINALITY a(f,ordinality)),
 ledger AS (SELECT x.* FROM XMLTABLE('/table/row' PASSING query_to_xml(
 CASE WHEN EXISTS(SELECT FROM pg_class WHERE oid=to_regclass('public.logistica_schema_migrations') AND relkind='r')
 THEN 'SELECT migration_name,migration_sha256,applied_at::text,applied_by FROM public.logistica_schema_migrations'
 ELSE 'SELECT NULL::text AS migration_name,NULL::text AS migration_sha256,NULL::text AS applied_at,NULL::text AS applied_by WHERE false' END,
 false,false,'') COLUMNS migration_name text PATH 'migration_name',migration_sha256 text PATH 'migration_sha256',applied_at text PATH 'applied_at',applied_by text PATH 'applied_by') x),
 issues(reason) AS (
 SELECT 'MISSING_EXTENSION:'||required.name FROM unnest(ARRAY['plpgsql','citext']) required(name) WHERE NOT EXISTS(SELECT FROM installed_extensions e WHERE e.name=required.name)
 UNION ALL SELECT 'UNEXPECTED_OBJECT:'||schema||'.'||name FROM application_objects o WHERE schema<>'public' OR NOT EXISTS(SELECT FROM expected_objects e WHERE e.catalog::regclass=o.classid AND e.name=o.name)
 UNION ALL SELECT 'MISSING_OBJECT:'||e.catalog||':'||e.name FROM expected_objects e WHERE NOT EXISTS(SELECT FROM application_objects o WHERE o.schema='public' AND o.classid=e.catalog::regclass AND o.name=e.name)
 UNION ALL SELECT 'TABLE_NOT_EMPTY_OR_UNSUPPORTED:'||name FROM counts WHERE oid IS NULL OR relkind<>'r' OR relpersistence<>'p' OR relrowsecurity OR relforcerowsecurity OR (name NOT IN ('logistica_schema_migrations','machine_family','machine_model','maintenance_template','template_section','template_task','template_task_inspection','plantilla_tecnicos') AND rows IS DISTINCT FROM 0)
 UNION ALL SELECT 'BASE_COLUMN_DRIFT:'||table_name||'.'||(c->>'name') FROM columns e
 LEFT JOIN pg_attribute a ON a.attrelid=to_regclass('public.'||table_name) AND a.attname=c->>'name' AND NOT a.attisdropped
 LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
 WHERE a.attnum IS DISTINCT FROM position::int OR format_type(a.atttypid,a.atttypmod) IS DISTINCT FROM c->>'type'
 OR a.attnotnull IS DISTINCT FROM (c->>'not_null')::boolean OR a.attidentity<>'' OR a.attgenerated<>''
 OR a.attcollation IS DISTINCT FROM CASE WHEN c->>'collation' IS NOT NULL THEN to_regcollation(format('%I',c->>'collation'))::oid ELSE (SELECT typcollation FROM pg_type WHERE oid=a.atttypid) END
 UNION ALL SELECT 'EXTRA_BASE_COLUMNS:'||(t->>'name') FROM base_tables WHERE (SELECT count(*) FROM pg_attribute WHERE attrelid=to_regclass('public.'||(t->>'name')) AND attnum>0 AND NOT attisdropped)<>jsonb_array_length(t->'columns')
 UNION ALL SELECT 'BASE_CONSTRAINT_DRIFT:'||table_name||'.'||(k->>'name') FROM constraints e LEFT JOIN pg_constraint a ON a.conrelid=to_regclass('public.'||table_name) AND a.conname=k->>'name'
 WHERE a.oid IS NULL OR a.contype::text<>k->>'type' OR NOT a.convalidated OR a.condeferrable OR a.condeferred
 OR (k->>'type'<>'c' AND (SELECT jsonb_agg(v.attname::text ORDER BY u.position) FROM unnest(a.conkey) WITH ORDINALITY u(attnum,position) JOIN pg_attribute v ON v.attrelid=a.conrelid AND v.attnum=u.attnum) IS DISTINCT FROM k->'columns')
 OR (k->>'type'='f' AND (a.confrelid IS DISTINCT FROM to_regclass('public.'||(k->>'reference')) OR a.confupdtype::text<>k->>'update' OR a.confdeltype::text<>k->>'delete' OR a.confmatchtype<>'s'
 OR (SELECT jsonb_agg(v.attname::text ORDER BY u.position) FROM unnest(a.confkey) WITH ORDINALITY u(attnum,position) JOIN pg_attribute v ON v.attrelid=a.confrelid AND v.attnum=u.attnum) IS DISTINCT FROM k->'reference_columns'))
 UNION ALL SELECT 'EXTRA_BASE_CONSTRAINTS:'||(t->>'name') FROM base_tables WHERE (SELECT count(*) FROM pg_constraint WHERE conrelid=to_regclass('public.'||(t->>'name')))<>jsonb_array_length(t->'constraints')
 UNION ALL SELECT 'BASE_INDEX_DRIFT:'||(i->>'name') FROM indexes LEFT JOIN pg_class c ON c.oid=to_regclass('public.'||(i->>'name')) LEFT JOIN pg_index x ON x.indexrelid=c.oid
 WHERE c.oid IS NULL OR x.indrelid IS DISTINCT FROM to_regclass('public.'||(i->>'table')) OR NOT x.indisvalid OR NOT x.indisready
 UNION ALL SELECT 'BASE_FUNCTION_DRIFT:'||(f->>'name') FROM functions LEFT JOIN pg_proc p ON p.oid=to_regprocedure('public.'||(f->>'name')||'(integer,integer,integer)')
 WHERE p.oid IS NULL OR p.prokind<>'f' OR p.prorettype<>'void'::regtype OR p.prosecdef OR p.proisstrict OR p.proleakproof OR p.proparallel<>'u' OR p.provolatile<>'v' OR p.proconfig IS DISTINCT FROM ARRAY['search_path=pg_catalog']::text[] OR p.prolang<>(SELECT oid FROM pg_language WHERE lanname='plpgsql') OR encode(sha256(convert_to(replace(p.prosrc,chr(13),''),'UTF8')),'hex') IS DISTINCT FROM f->>'hash'
 OR to_jsonb(p.proargnames) IS DISTINCT FROM f->'argnames' OR p.pronargs<>3 OR p.proargmodes IS NOT NULL OR p.provariadic<>0 OR p.prosupport<>0
 UNION ALL SELECT 'EXTRA_BASE_FUNCTION_OVERLOAD:'||p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('move_section','move_task','move_task_inspection') AND p.oid IS DISTINCT FROM to_regprocedure('public.'||p.proname||'(integer,integer,integer)')
 UNION ALL SELECT 'SEQUENCE_DRIFT:'||(s->>'name') FROM sequences LEFT JOIN pg_class c ON c.oid=to_regclass('public.'||(s->>'name')) LEFT JOIN pg_sequence q ON q.seqrelid=c.oid
 WHERE c.relkind IS DISTINCT FROM 'S' OR q.seqtypid IS DISTINCT FROM (s->>'type')::regtype OR q.seqstart<>1 OR q.seqincrement<>1 OR q.seqmin<>1 OR q.seqmax<>CASE WHEN s->>'type'='integer' THEN 2147483647::bigint ELSE 9223372036854775807::bigint END OR q.seqcache<>1 OR q.seqcycle
 OR to_regclass(pg_get_serial_sequence('public.'||(s->>'table'),s->>'column')) IS DISTINCT FROM to_regclass('public.'||(s->>'name'))
 OR c.relowner IS DISTINCT FROM (SELECT relowner FROM pg_class WHERE oid=to_regclass('public.'||(s->>'table')))
 OR NOT EXISTS(SELECT FROM pg_depend d JOIN pg_attribute a ON a.attrelid=d.refobjid AND a.attnum=d.refobjsubid WHERE d.classid='pg_class'::regclass AND d.objid=c.oid AND d.refclassid='pg_class'::regclass AND d.refobjid=to_regclass('public.'||(s->>'table')) AND a.attname=s->>'column' AND d.deptype='a')
 UNION ALL SELECT 'SEQUENCE_NOT_FRESH:'||(s->>'name') FROM sequence_state WHERE s->>'table' NOT IN ('machine_family','machine_model','maintenance_template','template_section','template_task','work_order','work_order_task') AND (last_value::bigint IS DISTINCT FROM 1 OR is_called::boolean IS DISTINCT FROM false)

 UNION ALL SELECT 'INDEX_CATALOG_DRIFT:'||(i->>'name') FROM indexes
 LEFT JOIN pg_class c ON c.oid=to_regclass('public.'||(i->>'name'))
 LEFT JOIN pg_index x ON x.indexrelid=c.oid LEFT JOIN pg_am am ON am.oid=c.relam
 WHERE c.relkind IS DISTINCT FROM 'i' OR c.relpersistence IS DISTINCT FROM 'p'
 OR x.indisunique IS DISTINCT FROM (i->>'unique')::boolean OR x.indisprimary IS DISTINCT FROM (i->>'primary')::boolean
 OR x.indisexclusion OR x.indnullsnotdistinct OR NOT x.indimmediate OR NOT x.indislive
 OR am.amname IS DISTINCT FROM 'btree' OR x.indnatts IS DISTINCT FROM jsonb_array_length(i->'columns')
 OR x.indnkeyatts IS DISTINCT FROM jsonb_array_length(i->'columns') OR x.indexprs IS NOT NULL
 OR (SELECT jsonb_agg(a.attname::text ORDER BY k.n) FROM unnest(x.indkey) WITH ORDINALITY k(attnum,n) LEFT JOIN pg_attribute a ON a.attrelid=x.indrelid AND a.attnum=k.attnum) IS DISTINCT FROM i->'columns'
 OR EXISTS(SELECT 1 FROM unnest(x.indoption) v WHERE v<>0)
 OR EXISTS(SELECT 1 FROM unnest(x.indclass,x.indcollation,x.indkey) k(opclass,colloid,attnum)
 LEFT JOIN pg_opclass opc ON opc.oid=k.opclass LEFT JOIN pg_attribute a ON a.attrelid=x.indrelid AND a.attnum=k.attnum
 WHERE NOT opc.opcdefault OR opc.opcnamespace IS DISTINCT FROM 'pg_catalog'::regnamespace
 OR opc.opcmethod IS DISTINCT FROM c.relam OR opc.opcintype IS DISTINCT FROM CASE WHEN a.atttypid='character varying'::regtype THEN 'text'::regtype ELSE a.atttypid END
 OR k.colloid IS DISTINCT FROM a.attcollation)
 UNION ALL SELECT 'MAPPING_FUNCTION_DRIFT' WHERE NOT EXISTS(
 SELECT 1 FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang
 WHERE p.oid=to_regprocedure('public.protect_logistica_legacy_owner_mapping()')
 AND p.prokind='f' AND p.prorettype='trigger'::regtype AND NOT p.proretset AND NOT p.prosecdef AND NOT p.proisstrict AND NOT p.proleakproof
 AND p.proparallel='u' AND p.provolatile='v' AND l.lanname='plpgsql'
 AND p.proconfig=ARRAY['search_path=pg_catalog']::text[] AND p.pronargs=0 AND p.pronargdefaults=0 AND p.proargnames IS NULL AND p.proallargtypes IS NULL AND p.proargmodes IS NULL AND p.provariadic=0 AND p.prosupport=0
 AND encode(sha256(convert_to(replace(p.prosrc,chr(13),''),'UTF8')),'hex')=(SELECT value->>'mappingFunctionHash' FROM expected))
 UNION ALL SELECT 'MAPPING_FUNCTION_OVERLOAD' FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname='protect_logistica_legacy_owner_mapping' AND p.oid IS DISTINCT FROM to_regprocedure('public.protect_logistica_legacy_owner_mapping()')
 UNION ALL SELECT 'TRIGGER_DRIFT:'||(e->>'name') FROM expected,LATERAL jsonb_array_elements(value->'triggers') e
 LEFT JOIN pg_trigger t ON t.tgrelid=to_regclass('public.logistica_legacy_owner_mapping') AND t.tgname=e->>'name' AND NOT t.tgisinternal
 WHERE t.oid IS NULL OR t.tgtype IS DISTINCT FROM (e->>'type')::smallint OR t.tgenabled IS DISTINCT FROM 'O'
 OR t.tgfoid IS DISTINCT FROM to_regprocedure('public.protect_logistica_legacy_owner_mapping()') OR t.tgnargs<>0 OR octet_length(t.tgargs)<>0
 OR cardinality(t.tgattr::smallint[])<>0 OR t.tgqual IS NOT NULL OR t.tgconstraint<>0 OR t.tgdeferrable OR t.tginitdeferred
 OR t.tgoldtable IS NOT NULL OR t.tgnewtable IS NOT NULL
 UNION ALL SELECT 'UNEXPECTED_TRIGGER:'||t.tgname FROM pg_trigger t WHERE NOT t.tgisinternal AND t.tgrelid IN (SELECT oid FROM counts)
 AND NOT EXISTS(SELECT 1 FROM expected,LATERAL jsonb_array_elements(value->'triggers') e WHERE t.tgrelid=to_regclass('public.logistica_legacy_owner_mapping') AND t.tgname=e->>'name')
 UNION ALL SELECT 'EXPRESSION_DEPENDENCY_DRIFT' WHERE EXISTS(
 SELECT 1 FROM pg_depend d JOIN pg_proc p ON d.refclassid='pg_proc'::regclass AND p.oid=d.refobjid
 WHERE p.pronamespace<>'pg_catalog'::regnamespace AND (
 (d.classid='pg_constraint'::regclass AND d.objid IN (SELECT oid FROM pg_constraint WHERE conrelid IN (SELECT oid FROM counts)))
 OR (d.classid='pg_attrdef'::regclass AND d.objid IN (SELECT oid FROM pg_attrdef WHERE adrelid IN (SELECT oid FROM counts)))
 OR (d.classid='pg_class'::regclass AND d.objid IN (SELECT indexrelid FROM pg_index WHERE indrelid IN (SELECT oid FROM counts)))))
 UNION ALL SELECT 'EXPRESSION_OPERATOR_DRIFT' WHERE EXISTS(
 SELECT 1 FROM pg_depend d JOIN pg_operator o ON d.refclassid='pg_operator'::regclass AND o.oid=d.refobjid
 WHERE o.oprnamespace<>'pg_catalog'::regnamespace AND (
 (d.classid='pg_constraint'::regclass AND d.objid IN (SELECT oid FROM pg_constraint WHERE conrelid IN (SELECT oid FROM counts)))
 OR (d.classid='pg_attrdef'::regclass AND d.objid IN (SELECT oid FROM pg_attrdef WHERE adrelid IN (SELECT oid FROM counts)))
 OR (d.classid='pg_class'::regclass AND d.objid IN (SELECT indexrelid FROM pg_index WHERE indrelid IN (SELECT oid FROM counts)))))
 UNION ALL SELECT 'CONSTRAINT_ATTRIBUTES_DRIFT:'||conname FROM pg_constraint WHERE conrelid IN (SELECT oid FROM counts) AND ((contype='c' AND connoinherit) OR NOT conislocal OR coninhcount<>0)
 UNION ALL SELECT 'BASE_FUNCTION_ATTRIBUTES_DRIFT:'||p.proname FROM pg_proc p WHERE p.oid IN (SELECT to_regprocedure('public.'||(f->>'name')||'(integer,integer,integer)') FROM functions) AND (p.proretset OR p.pronargdefaults<>0 OR p.proallargtypes IS NOT NULL)

 UNION ALL SELECT 'LEDGER_DRIFT' WHERE (SELECT count(*) FROM ledger)<>7 OR EXISTS(SELECT FROM ledger_expected e FULL JOIN ledger l ON l.migration_name=e.f->>'name' WHERE e.f IS NULL OR l.migration_name IS NULL OR l.migration_sha256 IS DISTINCT FROM e.f->>'sha256' OR l.applied_at IS NULL OR l.applied_by IS NULL)
 UNION ALL SELECT 'LEDGER_ORDER_DRIFT' WHERE EXISTS(SELECT FROM ledger_expected a JOIN ledger x ON x.migration_name=a.f->>'name' JOIN ledger_expected b ON b.position>a.position JOIN ledger y ON y.migration_name=b.f->>'name' WHERE x.applied_at::timestamptz>=y.applied_at::timestamptz)
 UNION ALL SELECT 'UNSUPPORTED_RULE_POLICY_OR_INHERITANCE' WHERE EXISTS(SELECT FROM pg_policy WHERE polrelid IN (SELECT oid FROM counts)) OR EXISTS(SELECT FROM pg_rewrite WHERE ev_class IN (SELECT oid FROM counts)) OR EXISTS(SELECT FROM pg_inherits WHERE inhrelid IN (SELECT oid FROM counts) OR inhparent IN (SELECT oid FROM counts))
)
 SELECT string_agg(reason,', ' ORDER BY reason) INTO problem FROM issues;
 IF problem IS NOT NULL THEN RAISE EXCEPTION 'PHASE_A_CLEANUP_SCHEMA_INVALID: %',problem; END IF;
END; $cleanup_schema$;
DO $seed_only$ DECLARE seed jsonb:='{"machine_family":[{"id":910001,"name":"TEST_LOCAL_CALIDAD_20261027_FAMILIA"}],"machine_model":[{"id":910001,"family_id":910001,"name":"TEST_LOCAL_CALIDAD_20261027_MODELO","manufacturer":"TEST_LOCAL_CALIDAD_20261027","bond_value":0,"standard_days":1}],"maintenance_template":[{"id":910001,"name":"TEST_LOCAL_CALIDAD_20261027_ENSAMBLE","template_type":"ENSAMBLE","model_id":910001,"version":1,"is_published":true,"created_by":"TEST_LOCAL_CALIDAD_20261027","created_at":"2026-01-01T00:00:00+00:00","updated_at":"2026-01-01T00:00:00+00:00"},{"id":910002,"name":"TEST_LOCAL_CALIDAD_20261027_INSPECCION","template_type":"INSPECCION","model_id":910001,"version":1,"is_published":true,"created_by":"TEST_LOCAL_CALIDAD_20261027","created_at":"2026-01-01T00:00:00+00:00","updated_at":"2026-01-01T00:00:00+00:00"}],"template_section":[{"id":910001,"template_id":910001,"title":"TEST_LOCAL_CALIDAD_20261027_SECCION","position":1},{"id":910002,"template_id":910002,"title":"Inspección de ensamble","position":1},{"id":910003,"template_id":910002,"title":"Inspección de pintura","position":2}],"template_task":[{"id":910001,"section_id":910001,"code":"TEST_LOCAL_TAREA","title":"TEST_LOCAL_CALIDAD_20261027_TAREA","expected_minutes":1,"required":true,"position":1,"category":"Ensamble"},{"id":910002,"section_id":910001,"code":"LIB001","title":"TEST_LOCAL_CALIDAD_20261027_LIBERACION_ENSAMBLE","expected_minutes":1,"required":true,"position":2,"category":"Ensamble"},{"id":910003,"section_id":910001,"code":"LIB002","title":"TEST_LOCAL_CALIDAD_20261027_LIBERACION_PINTURA","expected_minutes":1,"required":true,"position":3,"category":"Ensamble"}],"template_task_inspection":[{"id":910001,"section_id":910002,"revision_point":"TEST_LOCAL_CALIDAD_20261027_PUNTO_ENSAMBLE","specs":"TEST_LOCAL_CALIDAD_20261027","suggestions":"TEST_LOCAL_CALIDAD_20261027","required":true,"position":1,"category":"Mecanica"},{"id":910002,"section_id":910003,"revision_point":"TEST_LOCAL_CALIDAD_20261027_PUNTO_PINTURA","specs":"TEST_LOCAL_CALIDAD_20261027","suggestions":"TEST_LOCAL_CALIDAD_20261027","required":true,"position":1,"category":"Mecanica"}],"plantilla_tecnicos":[{"id":910001,"estatus":"Activo","sucursal":"TEST_LOCAL","nombre_tecnico":"TEST_LOCAL_CALIDAD_20261027_OPERADOR","correo_tecnico":"test_local_operador@example.invalid","telefono":null,"puesto":"Operador de producción","nombre_bonos":"TEST_LOCAL_CALIDAD_20261027","numero_empleado":null},{"id":910002,"estatus":"Activo","sucursal":"TEST_LOCAL","nombre_tecnico":"TEST_LOCAL_CALIDAD_20261027_CALIDAD","correo_tecnico":"test_local_calidad@example.invalid","telefono":null,"puesto":"Supervisor de calidad","nombre_bonos":"TEST_LOCAL_CALIDAD_20261027","numero_empleado":null}]}'::jsonb; t text; expected jsonb; actual jsonb; BEGIN
 FOR t,expected IN SELECT e.key,r.value FROM jsonb_each(seed) e,LATERAL jsonb_array_elements(e.value) r LOOP
  EXECUTE format('SELECT to_jsonb(a) FROM ONLY public.%I a WHERE id=$1',t) INTO actual USING (expected->>'id')::int;
  IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'ORIGINAL_SEED_MISSING_OR_CHANGED: %',t; END IF;
 END LOOP;
 FOR t,actual IN SELECT 'machine_family'::text,to_jsonb(a) FROM ONLY public.machine_family a
 UNION ALL SELECT 'machine_model'::text,to_jsonb(a) FROM ONLY public.machine_model a
 UNION ALL SELECT 'maintenance_template'::text,to_jsonb(a) FROM ONLY public.maintenance_template a
 UNION ALL SELECT 'template_section'::text,to_jsonb(a) FROM ONLY public.template_section a
 UNION ALL SELECT 'template_task'::text,to_jsonb(a) FROM ONLY public.template_task a
 UNION ALL SELECT 'template_task_inspection'::text,to_jsonb(a) FROM ONLY public.template_task_inspection a
 UNION ALL SELECT 'plantilla_tecnicos'::text,to_jsonb(a) FROM ONLY public.plantilla_tecnicos a LOOP
  IF NOT (seed->t) @> jsonb_build_array(actual) THEN RAISE EXCEPTION 'RUNTIME_ROWS_REMAIN: %',t; END IF;
 END LOOP;
END; $seed_only$;
